commands:
awk '
BEGIN {
  print "=== Log Analysis ==="
  error_count = 0
  warn_count = 0
}
{
  timestamp = $1
  level = $2
  category = $3

  if (level == "ERROR") {
    error_count++
    errors[category]++
    times[error_count] = timestamp
  } else if (level == "WARN") {
    warn_count++
  }
}
END {
  print "Total Errors: " error_count
  print "Total Warnings: " warn_count
  print ""
  print "Error Categories:"
  for (cat in errors) {
    print "  " cat ": " errors[cat]
  }
}
' /work/logs/app.log
